#!/usr/bin/env bash
# Generates <target>/nerves_defconfig, <target>/Config.in and
# <target>/rootfs_overlay/etc/erlinit.config from the vendored <target>/base/
# plus the target's *.fragment files. With --check, writes nothing and exits
# non-zero if a generated file has drifted.
#
# nerves_defconfig merge rules:
#   - NERVES_DEFCONFIG_DIR is the target dir, so base BR2_ lines get
#     ${NERVES_DEFCONFIG_DIR}/ -> ${NERVES_DEFCONFIG_DIR}/base/. Fragment
#     paths are never rewritten.
#   - A fragment `BR2_X=...` or `# BR2_X is not set` drops base's line for X
#     (either form) and is emitted in the trailing product section, so every
#     symbol appears once.
#   - For the LIST_SYMS below the fragment value is appended to base's line in
#     place, so base entries keep their position; base must set the symbol.
set -euo pipefail

LIST_SYMS="BR2_GLOBAL_PATCH_DIR BR2_ROOTFS_OVERLAY BR2_ROOTFS_POST_BUILD_SCRIPT
BR2_ROOTFS_POST_IMAGE_SCRIPT BR2_ROOTFS_POST_FAKEROOT_SCRIPT BR2_ROOTFS_USERS_TABLES
BR2_LINUX_KERNEL_CONFIG_FRAGMENT_FILES BR2_LINUX_KERNEL_PATCH
BR2_LINUX_KERNEL_INTREE_DTS_NAME BR2_LINUX_KERNEL_CUSTOM_DTS_PATH
BR2_PACKAGE_BUSYBOX_CONFIG_FRAGMENT_FILES BR2_NERVES_ADDITIONAL_IMAGE_FILES
BR2_TARGET_GRUB2_BUILTIN_MODULES_EFI"

# Toolchain and Buildroot must match what base was proven against.
PINNED_DEPS="nerves_system_br nerves_toolchain_aarch64_nerves_linux_gnu"

usage() {
    echo "usage: $0 <target> [--check]" >&2
    exit 2
}

[ $# -ge 1 ] && [ $# -le 2 ] || usage
t=${1%/}
check=0
if [ $# -eq 2 ]; then
    [ "$2" = --check ] || usage
    check=1
fi
base=$t/base

for f in "$base/nerves_defconfig" "$base/Config.in" \
    "$base/rootfs_overlay/etc/erlinit.config" "$base/mix.exs" "$t/mix.exs" \
    "$t/nerves_defconfig.fragment" "$t/Config.in.fragment" \
    "$t/erlinit.config.fragment"; do
    [ -f "$f" ] || { echo "sync-base: missing $f" >&2; exit 1; }
done

dep_version() {
    sed -n "s/.*{:$2, *\"\([^\"]*\)\".*/\1/p" "$1" | head -n 1
}

status=0
for dep in $PINNED_DEPS; do
    want=$(dep_version "$base/mix.exs" "$dep")
    have=$(dep_version "$t/mix.exs" "$dep")
    if [ -z "$want" ] || [ "$want" != "$have" ]; then
        echo "PIN: $t/mix.exs has $dep \"$have\", base/mix.exs has \"$want\"" >&2
        status=1
    fi
done
[ $status -eq 0 ] || exit 1

out=$(mktemp -d)
trap 'rm -rf "$out"' EXIT

awk -v lists="$LIST_SYMS" '
function sym_of(line,   s) {
    if (match(line, /^BR2_[A-Za-z0-9_]+=/))
        return substr(line, 1, RLENGTH - 1)
    if (line ~ /^# BR2_[A-Za-z0-9_]+ is not set$/) {
        s = substr(line, 3)
        sub(/ is not set$/, "", s)
        return s
    }
    return ""
}
function value_of(line, s,   v) {
    v = substr(line, length(s) + 2)
    if (v ~ /^".*"$/)
        v = substr(v, 2, length(v) - 2)
    return v
}
function fail(msg) {
    print "sync-base: " msg > "/dev/stderr"
    failed = 1
    exit 1
}
BEGIN {
    n = split(lists, l, /[ \n]+/)
    for (i = 1; i <= n; i++)
        is_list[l[i]] = 1
}
FILENAME == ARGV[1] {
    s = sym_of($0)
    if (s != "") {
        if (s in seen)
            fail("nerves_defconfig.fragment sets " s " twice")
        seen[s] = 1
        if ((s in is_list) && $0 ~ /^BR2_/) {
            append[s] = value_of($0, s)
            next
        }
        override[s] = 1
    }
    frag[++nfrag] = $0
    next
}
{
    line = $0
    s = sym_of(line)
    if (s in override)
        next
    if (line ~ /^BR2_/) {
        gsub(/[$][{]NERVES_DEFCONFIG_DIR[}]\//, "${NERVES_DEFCONFIG_DIR}/base/", line)
        if (s in append) {
            v = value_of(line, s)
            line = s "=\"" (v == "" ? "" : v " ") append[s] "\""
            merged[s] = 1
        }
    }
    body[++nbody] = line
}
END {
    if (failed)
        exit 1
    for (s in append)
        if (!(s in merged))
            fail("nerves_defconfig.fragment appends to list " s ", which base/nerves_defconfig does not set")
    print "# GENERATED by scripts/sync-base.sh from base/nerves_defconfig + nerves_defconfig.fragment. DO NOT EDIT."
    for (i = 1; i <= nbody; i++)
        print body[i]
    print ""
    print "# ---- product layer: nerves_defconfig.fragment ----"
    for (i = 1; i <= nfrag; i++)
        print frag[i]
}
' "$t/nerves_defconfig.fragment" "$base/nerves_defconfig" >"$out/nerves_defconfig"

{
    echo "# GENERATED by scripts/sync-base.sh from base/Config.in + Config.in.fragment. DO NOT EDIT."
    sed 's|\$NERVES_DEFCONFIG_DIR/|$NERVES_DEFCONFIG_DIR/base/|g' "$base/Config.in"
    echo
    echo "# ---- product layer: Config.in.fragment ----"
    cat "$t/Config.in.fragment"
} >"$out/Config.in"

{
    cat "$base/rootfs_overlay/etc/erlinit.config"
    echo
    echo "# ---- product layer: erlinit.config.fragment ----"
    cat "$t/erlinit.config.fragment"
} >"$out/erlinit.config"

dests="nerves_defconfig:$t/nerves_defconfig Config.in:$t/Config.in erlinit.config:$t/rootfs_overlay/etc/erlinit.config"
for pair in $dests; do
    src=$out/${pair%%:*}
    dest=${pair#*:}
    if [ $check -eq 1 ]; then
        cmp -s "$src" "$dest" || { echo "DRIFT: $dest (run 'make sync')"; status=1; }
    else
        install -D -m 0644 "$src" "$dest"
        echo "generated $dest"
    fi
done
exit $status
